import { useState } from 'react';

function UserProfile() {
 const [user, setUser] = useState({
 name: "Prince",
 xp: 150,
 coins: 30,
 completedLessons: [1,2,3]
 });

 function addXP() {
 // ❌ WRONG: user.xp += 50 - mutating state directly!
 // ✅ CORRECT: Create new object with spread operator
 setUser({
...user, // Keep all old properties
 xp: user.xp + 50 // Update only xp
 });
 }

 function completeLesson(lessonId) {
 setUser({
...user,
 completedLessons: [...user.completedLessons, lessonId], // Add to array immutably
 xp: user.xp + 50
 });
 }

 return (
 <div>
 <p>{user.name} - {user.xp} XP - {user.coins} coins</p>
 <p>Completed: {user.completedLessons.join(", ")}</p>
 <button onClick={addXP}>Add 50 XP</button>
 <button onClick={() => completeLesson(4)}>Complete Lesson 4</button>
 </div>
 );
}

