import { useState, useEffect } from 'react';

function XPTracker() {
 const [xp, setXp] = useState(0);
 const [coins, setCoins] = useState(0);

 // Effect 1: Run only once - Load saved XP on mount
 useEffect(() => {
 const savedXP = localStorage.getItem("xp");
 if (savedXP) setXp(Number(savedXP));
 console.log("Loaded XP from storage");
 }, []); // Empty = mount only

 // Effect 2: Run when xp changes - Save XP whenever it changes
 useEffect(() => {
 localStorage.setItem("xp", xp);
 console.log(`XP saved: ${xp}`);
 }, [xp]); // Watch xp - when xp changes, save

 // Effect 3: Run when coins changes - Different save
 useEffect(() => {
 localStorage.setItem("coins", coins);
 }, [coins]);

 return (
 <div>
 <p>XP: {xp} Coins: {coins}</p>
 <button onClick={() => setXp(xp + 10)}>+10 XP</button>
 <button onClick={() => setCoins(coins + 5)}>+5 Coins</button>
 </div>
 );
}
// Click +10 XP -> Effect 2 runs -> saves to localStorage
// Click +5 Coins -> Effect 3 runs -> saves coins

import { useState, useEffect } from 'react';

function LiveClock() {
 const [time, setTime] = useState(new Date().toLocaleTimeString());

 useEffect(() => {
 console.log("Clock mounted - Starting interval");
 const interval = setInterval(() => {
 setTime(new Date().toLocaleTimeString());
 }, 1000);

 // CLEANUP: Runs when component unmounts or before next effect
 return () => {
 console.log("Clock unmounting - Clearing interval");
 clearInterval(interval); // Stop timer, prevent memory leak!
 };
 }, []); // Empty = set interval once on mount, cleanup on unmount

 return <p>Time: {time}</p>;
}

function App() {
 const [showClock, setShowClock] = useState(true);
 return (
 <div>
 <button onClick={() => setShowClock(!showClock)}>{showClock? "Hide" : "Show"} Clock</button>
 {showClock && <LiveClock />}
 </div>
 );
}
// Click Hide -> LiveClock unmounts -> cleanup runs -> interval cleared
// No cleanup = interval keeps running even when hidden = bug!

import { useState, useEffect, useRef } from 'react';

function SearchWithFocus() {
 const [search, setSearch] = useState("");
 const inputRef = useRef(null); // Create ref
 const renderCount = useRef(0); // Count renders without triggering re-render

 useEffect(() => {
 renderCount.current++; // Update ref, no re-render triggered
 console.log(`Rendered ${renderCount.current} times`);
 });

 function handleFocus() {
 inputRef.current.focus(); // Directly focus input DOM element
 inputRef.current.style.border = "2px solid #61dafb";
 }

 return (
 <div>
 <input 
 ref={inputRef} // Attach ref to input
 value={search}
 onChange={(e) => setSearch(e.target.value)}
 placeholder="Search lessons..."
 />
 <button onClick={handleFocus}>Focus Input</button>
 <p>Render count (via ref): {renderCount.current}</p>
 </div>
 );
}
// Click Focus Input -> input gets focused and blue border - direct DOM access via ref

import { useState, useEffect } from 'react';

function Dashboard() {
 const [user, setUser] = useState(null);
 const [lessons, setLessons] = useState([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);

 useEffect(() => {
 let isMounted = true; // Flag to prevent state update if unmounted

 async function fetchDashboardData() {
 try {
 setLoading(true);
 // Simulate Firebase calls: getDoc(doc(db, 'users', userId))
 await new Promise(resolve => setTimeout(resolve, 1500)); // Simulate network delay

 if (!isMounted) return; // Don't update if component unmounted

 const userData = { xp: 120, coins: 30, completed: [1,2] };
 const lessonsData = [
 {id: 1, title: "Introduction", status: "completed"},
 {id: 2, title: "JSX", status: "current"},
 ];

 setUser(userData);
 setLessons(lessonsData);
 } catch (err) {
 if (isMounted) setError("Failed to load course");
 } finally {
 if (isMounted) setLoading(false);
 }
 }

 fetchDashboardData();

 return () => {
 isMounted = false; // Cleanup: Mark as unmounted so no state update after unmount
 console.log("Dashboard unmounted - canceling fetch");
 };
 }, []); // Empty = fetch once on mount - exactly like your authentication.js code!

 if (loading) return <div className="loading"><div className="spinner"></div>Loading your course...</div>;
 if (error) return <p>{error}</p>;
 return <div>Welcome {user.xp} XP - {lessons.length} lessons loaded</div>;
}

import { useState, useEffect, useRef } from 'react';

function App() {
 const [lessons, setLessons] = useState([]);
 const [loading, setLoading] = useState(true);
 const [xp, setXp] = useState(0);
 const [studyTime, setStudyTime] = useState(0);
 const searchRef = useRef(null);

 // Effect 1: Initial load like Firebase (mount once)
 useEffect(() => {
 const timer = setTimeout(() => {
 setLessons([
 {id: 1, title: "Introduction to React", status: "completed"},
 {id: 2, title: "JSX and Components", status: "current"},
 {id: 3, title: "Props", status: "locked"},
 ]);
 setXp(100);
 setLoading(false);
 }, 1000);
 return () => clearTimeout(timer);
 }, []);

 // Effect 2: Study timer - runs every second, cleanup on unmount
 useEffect(() => {
 const interval = setInterval(() => setStudyTime(t => t + 1), 1000);
 return () => clearInterval(interval);
 }, []);

 // Effect 3: Auto-save XP when xp changes
 useEffect(() => {
 if (xp > 0) {
 localStorage.setItem("xp", xp);
 console.log(`Auto-saved XP: ${xp}`);
 }
 }, [xp]);

 // Effect 4: Focus search on mount
 useEffect(() => {
 if (searchRef.current) searchRef.current.focus();
 }, []);

 function completeLesson(id) {
 setLessons(lessons.map(l => l.id===id? {...l, status: 'completed'} : l.id===id+1? {...l, status: 'current'} : l));
 setXp(prev => prev + 50); // Functional update - safe for rapid clicks
 }

 if (loading) return <div style={{padding: '40px', textAlign: 'center'}}>Loading your course... (useEffect fetching)</div>;

 return (
 <div style={{background: '#07111f', color: 'white', minHeight: '100vh', padding: '20px'}}>
 <div style={{display: 'flex', gap: '10px', flexWrap: 'wrap'}}>
 <span>⚡ {xp} XP (auto-saved via useEffect)</span>
 <span>⏱️ Study: {studyTime}s (via useEffect interval)</span>
 <span>📚 {lessons.filter(l => l.status==='completed').length}/{lessons.length}</span>
 </div>
 <input ref={searchRef} placeholder="Search (auto-focused via useRef)" style={{marginTop: '15px', padding: '8px', width: '100%'}} />
 <div style={{marginTop: '20px', display: 'grid', gap: '10px'}}>
 {lessons.map(l => (
 <div key={l.id} style={{border: '1px solid #61dafb', padding: '15px', borderRadius: '12px'}}>
 <p>{l.title} - {l.status}</p>
 {l.status==='current' && <button onClick={() => completeLesson(l.id)}>Complete +50 XP</button>}
 </div>
 ))}
 </div>
 <p style={{marginTop: '20px', color: '#94a3b8', fontSize: '12px'}}>Check console: useEffect logs for mount, XP save, timer. Try leaving page - interval cleanup prevents leak!</p>
 </div>
 );
}
export default App;
